var n=`1081-arroz-caldo`;var t=`world-1081`;var s=`PH`;var a=`southeast-asia`;var o=4;var r=57;var g={en:`Arroz Caldo`,ua:`Арроз кальдо`};var d={en:`Arroz Caldo is a dish from Philippines prepared with chicken thigh, garlic, yellow onion, glutinous rice. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Арроз кальдо, страва кухні країни Філіппіни, яку готують із таких продуктів: куряче стегно, часник, жовта цибуля, клейкий рис. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`chicken-thigh`,550,`g`],[`ground-ginger`,40,`g`],[`garlic`,5,`clove`],[`yellow-onion`,150,`g`],[`canola-oil`,40,`ml`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 33 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 33 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:33,i:[[`glutinous-rice`,260,`g`],[`white-rice`,130,`g`],[`chicken-stock`,1250,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,32,`ml`],[`ground-black-pepper`,4,`g`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,3,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,40,`g`]]}];var l={slug:n,id:t,country:`PH`,region:a,servings:4,minutes:57,title:g,text:d,steps:h};export{s as country,l as default,t as id,r as minutes,a as region,o as servings,n as slug,h as steps,d as text,g as title};